from AlgorithmImports import *


class ExactStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, Market.USA, False
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_close_count = 0

    def OnData(self, data):
        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]

            if self.previous_aapl_close is not None and aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close
            self.aapl_close_count += 1
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values())

        if all_bars_present:
            self.EvaluateStrategies(previous_spy_close, previous_spy_sma, data)

        if data.Bars.ContainsKey(self.spy):
            self.previous_spy_close = data.Bars[self.spy].Close
            self.previous_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None

    def EvaluateStrategies(self, previous_spy_close, previous_spy_sma, data):
        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady or self.aapl_close_count < 4:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close
        current_spy_sma = self.spy_sma.Current.Value

        spy_crosses_above = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close <= previous_spy_sma
            and spy_close > current_spy_sma
        )

        spy_crosses_below = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close >= previous_spy_sma
            and spy_close < current_spy_sma
        )

        if self.Portfolio[self.spy].Invested:
            if spy_crosses_below and not self.Transactions.GetOpenOrders(self.spy):
                self.Liquidate(self.spy)
        elif spy_crosses_above and not self.Transactions.GetOpenOrders(self.spy):
            self.SetHoldings(self.spy, 0.40)

        if self.Portfolio[self.aapl].Invested:
            if self.aapl_rsi.Current.Value > 60 and not self.Transactions.GetOpenOrders(self.aapl):
                self.Liquidate(self.aapl)
        elif self.aapl_red_streak >= 3 and not self.Transactions.GetOpenOrders(self.aapl):
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
